#!/usr/bin/env bash
# Every commit in BASE..HEAD carries a Signed-off-by matching its author.
#
# Kept out of the workflow YAML so it can be run — and tested — locally:
#     bash .github/scripts/check-dco.sh origin/main HEAD
set -euo pipefail

BASE="${1:?usage: check-dco.sh <base-ref> <head-ref>}"
HEAD="${2:?usage: check-dco.sh <base-ref> <head-ref>}"

missing=""
mismatched=""
checked=0

# --no-merges: a merge commit is generated by GitHub's own UI, so there is no
# author to certify anything.
for sha in $(git rev-list --no-merges "$BASE..$HEAD"); do
  author=$(git log -1 --format=%ae "$sha" | tr '[:upper:]' '[:lower:]')
  committer=$(git log -1 --format=%ce "$sha" | tr '[:upper:]' '[:lower:]')
  subject=$(git log -1 --format=%s "$sha")

  # A bot can't certify something it can't read; its commits belong to whoever
  # ran the automation.
  case "$author" in
    *"[bot]"* | *"bot@"*)
      echo "skip  ${sha:0:8}  $subject  (bot)"
      continue
      ;;
  esac

  checked=$((checked + 1))

  # Trailer form: "Signed-off-by: Real Name <email@example.com>"
  signers=$(git log -1 --format=%B "$sha" |
    grep -iE '^[[:space:]]*Signed-off-by:[[:space:]]*.+<.+@.+>' |
    sed -E 's/.*<[[:space:]]*([^>]+)[[:space:]]*>.*/\1/' |
    tr '[:upper:]' '[:lower:]' || true)

  if [ -z "$signers" ]; then
    missing="${missing}  ${sha:0:8}  ${subject}"$'\n'
    continue
  fi

  # The sign-off has to be the person who wrote or committed it — otherwise
  # anyone could certify on someone else's behalf.
  if ! printf '%s\n' "$signers" | grep -qxF "$author" &&
    ! printf '%s\n' "$signers" | grep -qxF "$committer"; then
    mismatched="${mismatched}  ${sha:0:8}  ${subject}"$'\n'
    mismatched="${mismatched}      signed off by: $(printf '%s' "$signers" | tr '\n' ' ')"$'\n'
    mismatched="${mismatched}      authored by:   ${author}"$'\n'
  fi
done

if [ -z "$missing" ] && [ -z "$mismatched" ]; then
  echo "All ${checked} commit(s) carry a valid Signed-off-by."
  exit 0
fi

report() {
  echo "### DCO check failed"
  echo
  echo "Signing off certifies the [Developer Certificate of Origin]"
  echo "(https://developercertificate.org/): that you wrote this code, or"
  echo "otherwise have the right to submit it under the project's Apache-2.0"
  echo "license."
  echo
  if [ -n "$missing" ]; then
    echo "**No \`Signed-off-by\` trailer:**"
    echo '```'
    printf '%s' "$missing"
    echo '```'
  fi
  if [ -n "$mismatched" ]; then
    echo "**\`Signed-off-by\` does not match the commit author or committer:**"
    echo '```'
    printf '%s' "$mismatched"
    echo '```'
  fi
  echo "**To fix:** sign off new commits with \`git commit -s\`, and repair the"
  echo "ones already pushed with:"
  echo
  echo '```'
  echo "git rebase --signoff ${BASE}"
  echo "git push --force-with-lease"
  echo '```'
  echo
  echo "\`git config --global format.signOff true\` makes it the default."
}

report
# On CI, also render it on the run's summary page rather than only in the log.
if [ -n "${GITHUB_STEP_SUMMARY:-}" ]; then
  report >>"$GITHUB_STEP_SUMMARY"
fi

exit 1
